const {projects} = await tools.call("bench.list-projects", {});
let project_count = 0;
let billable_minutes = 0;
for (const project of projects) {
    if (project.region !== "north" || project.status !== "active") continue;
    const detail = await tools.call("bench.project-detail", {detail_key: project.detail_key});
    project_count++;
    billable_minutes += detail.billable_minutes;
}
return {project_count, billable_minutes};
